    type: "historical-site",
    parent: "TW-NWT",
    coords: [121.4553, 25.0108],
    name: {
      de: "Lin-Familienanwesen und Garten",
      hu: "Lin Család Kúriája és Kertje",
      ro: "Conacul și Grădina Familiei Lin",
      en: "Lin Family Mansion and Garden"},
    image: "/poi-images/lin-family-mansion-and-garden-history-v2.webp",
    description: {
      de: "Eines der besterhaltenen Beispiele traditioneller chinesischer Architektur und Gartenkunst in Taiwan.",
      hu: "A hagyományos kínai építészet és kertművészet egyik legjobban megőrzött példája Tajvanon.",
      ro: "Unul dintre cele mai bine conservate exemple de arhitectură și peisagistică tradițională chineză din Taiwan.",
      en: "One of the best-preserved examples of traditional Chinese architecture and gardening in Taiwan.",
      es: "Uno de los ejemplos mejor conservados de arquitectura tradicional china y arte de jardinería en Taiwán.",
      pt: "Um dos exemplos mais bem preservados da arquitetura tradicional chinesa e arte de jardinagem em Taiwan.",
      fr: "L'un des exemples les mieux conservés de l'architecture traditionnelle chinoise et de l'art des jardins à Taïwan.",
    },
    facts: {
      de: ["Wurde 1851 erbaut.", "Umfasst eine Fläche von 20.000 Quadratmetern."],
      hu: ["1851-ben épült.", "Területe mintegy 20 000 négyzetméter."],
      ro: ["Construit în 1851.", "Acoperă o suprafață de 20.000 de metri pătrați."],
      en: ["Built in 1851.", "Covers an area of 20,000 square meters."],
      es: ["Fue construida en 1851.", "Abarca una superficie de 20.000 metros cuadrados."],
      pt: ["Foi construída em 1851.", "Abrange uma área de 20.000 metros quadrados."],
      fr: ["A été construite en 1851.", "Couvre une superficie de 20 000 mètres carrés."],
    }, image: "/poi-images/lin-family-mansion-and-garden-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Lin-Familienanwesen und der dazugehörige Garten in Banqiao, Neu-Taipeh, gelten als das prachtvollste Beispiel für die Architektur der Qing-Dynastie in Taiwan. Die Anlage wurde ab 1851 von der wohlhabenden Familie Lin Ben-Yuan errichtet und umfasst eine Fläche von rund 20.000 Quadratmetern. Die Architektur zeichnet sich durch kunstvolle Holzschnitzereien, geschwungene Dächer und prächtige Pavillons aus, die harmonisch in eine künstlich angelegte Gartenlandschaft eingebettet sind. Einzigartig sind die verschiedenen Wasserbecken, Steinbrücken und künstlichen Hügel, die nach den Prinzipien des Feng Shui gestaltet wurden. Der Garten diente nicht nur als Wohnsitz, sondern auch als Ort für gesellschaftliche Zusammenkünfte und kulturelle Veranstaltungen. Heute ist das Anwesen ein geschütztes Kulturdenkmal, das Besuchern einen tiefen Einblick in den luxuriösen Lebensstil und die Gartenkunst des 19. Jahrhunderts bietet.",
      hu: "A Tajpej Banqiao negyedében található Lin Család Kúriája és Kertje a Qing-dinasztia korabeli építészet legszebb és legépebben megőrzött példája Tajvanon. Az építkezést 1851-ben kezdte el a tehetős Lin Ben-Yuan család, és a komplexum végül mintegy 20 000 négyzetméteres területet foglalt el. A kúria épületeit finom fafaragások, jellegzetes íves tetők és díszes pavilonok jellemzik, amelyek szerves egységet alkotnak a gondosan tervezett tájképi kerttel. A kertben mesterséges tavak, elegáns kőhidak és sziklakertek találhatók, amelyeket a fengsuj elvei alapján alakítottak ki a tökéletes harmónia elérése érdekében. Az ingatlan egykor nemcsak családi otthonként, hanem fontos társadalmi és kulturális események helyszíneként is szolgált. Ma védett műemlék, amely lenyűgöző bepillantást enged a 19. századi tajvani elit fényűző életmódjába és esztétikai világába.",
      ro: "Conacul și Grădina Familiei Lin, situate în districtul Banqiao din New Taipei City, reprezintă cel mai rafinat exemplu de arhitectură rezidențială și peisagistică din perioada dinastiei Qing în Taiwan. Construcția a fost inițiată în 1851 de bogata familie Lin Ben-Yuan, întinzându-se pe o suprafață impresionantă de aproximativ 20.000 de metri pătrați. Complexul se distinge prin sculpturile sale detaliate în lemn, acoperișurile curbate tradiționale și pavilioanele elegante, toate integrate armonios într-o grădină clasică chineză. Elementele de apă, podurile de piatră și dealurile artificiale au fost dispuse conform principiilor Feng Shui pentru a crea un spațiu de o estetică impecabilă. Pe lângă rolul de locuință, proprietatea a servit ca centru pentru întâlniri sociale și evenimente culturale de prestigiu. În prezent, acest monument istoric oferă vizitatorilor o fereastră fascinantă spre stilul de viață luxos și arta grădinăritului din secolul al XIX-lea.",
      en: "The Lin Family Mansion and Garden in Banqiao, New Taipei City, is widely regarded as the finest and most complete example of Qing Dynasty residential architecture in Taiwan. Construction began in 1851 by the wealthy Lin Ben-Yuan family, eventually encompassing a sprawling 20,000-square-meter estate. The site is renowned for its intricate wood carvings, sweeping swallow-tail ridges, and ornate pavilions that blend seamlessly into a meticulously crafted classical garden. Water features, arched stone bridges, and artificial rock formations were strategically placed according to Feng Shui principles to achieve aesthetic and spiritual harmony. Historically, the mansion was not only a private residence but also a venue for high-society gatherings and cultural exchange. Today, it stands as a preserved historical site, offering a profound look into the opulent lifestyle and sophisticated landscaping artistry of 19th-century Taiwan.",
      es: "La Mansión y Jardín de la Familia Lin es una residencia histórica en Banqiao, Nuevo Taipéi, Taiwán. Fue construida en el siglo XIX por la rica familia Lin, originaria de Fujian. El jardín es uno de los jardines chinos tradicionales más bellos de Taiwán, con pabellones, estanques y paisajes artísticos. La propiedad incluye varios patios y salones que reflejan la riqueza y el estatus social de la familia. El lugar es un monumento histórico nacional y un destino popular para los turistas que buscan una visión de la vida de la clase alta en la China imperial.",
      pt: "A Mansão e Jardim da Família Lin é uma residência histórica em Banqiao, Novo Taipé, Taiwan. Foi construída no século XIX pela rica família Lin, originária de Fujian. O jardim é um dos jardins chineses tradicionais mais belos de Taiwan, com pavilhões, lagos e paisagens artísticas. A propriedade inclui vários pátios e salões que refletem a riqueza e o status social da família. O local é um monumento histórico nacional e um destino popular para turistas que buscam uma visão da vida da classe alta na China imperial.",
      fr: "La demeure et le jardin de la famille Lin est une résidence historique à Banqiao, à Nouveau Taipei, à Taïwan. Elle a été construite au XIXe siècle par la riche famille Lin, originaire du Fujian. Le jardin est l'un des plus beaux jardins chinois traditionnels de Taïwan, avec ses pavillons, ses étangs et ses paysages artistiques. La propriété comprend plusieurs cours et salles qui reflètent la richesse et le statut social de la famille. Le site est un monument historique national et une destination populaire pour les touristes qui cherchent à découvrir la vie de la classe supérieure dans la Chine impériale.",
    },
